        'cart' as step,
        2 as step_order,
        count(*) as total_events,
        uniq(user_id) as unique_users
      FROM ProductEvent
      WHERE event_type = 'cart'

      UNION ALL

      SELECT
        'purchase' as step,
        3 as step_order,
        count(*) as total_events,
        uniq(user_id) as unique_users
      FROM ProductEvent
      WHERE event_type = 'purchase'

      ORDER BY step_order
    `);
    return result.json();
  }
